// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 futureTime) public {
        vm.assume(actor != address(0));
        vm.warp(1000);
        vm.assume(futureTime > 1000);
        amount = bound(amount, 0, 100 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(futureTime);

        (uint256 recordedUnlock, ) = c.Acc(actor);
        assertTrue(recordedUnlock >= futureTime);
    }
}
